approved_command_preview:
$ErrorActionPreference = 'Stop'
$repo = [Environment]::GetEnvironmentVariable('DCOIR_REPO_ROOT','Machine')
$branches = @('noop-do-not-create','noop-do-not-create-2','noop-do-not-create-3','noop-do-not-create-4')
foreach ($branch in $branches) {
  $existing = git -C $repo ls-remote --heads origin "refs/heads/$branch"
  if ($existing) { git -C $repo push origin --delete $branch }
}
foreach ($branch in $branches) {
  $remaining = git -C $repo ls-remote --heads origin "refs/heads/$branch"
  if ($remaining) { throw "Branch still exists after cleanup: $branch" }
}
Write-Host 'Accidental noop branches are absent from origin.'

